Method.Implementation:
#dim tSC As %Status = $$$OK
 Set comment = ""
  Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "In DeployFiles, deploy " _compNm _ " type: " _  fileType)

 set ..DeployDirectory = $$$USRRELEASEBASEDIR _ usrNm _ $$$SVNSRCTRUNK
 set ..DeployLogDirectory = $$$USRRELEASEBASEDIR _  usrNm _ $$$LOGDIR

 set cfgFileType = "CONFIG" 
 set clsFileType = "CLS"

 Set tProductionClassIncluded = 0
 NEW $NAMESPACE
 try {
 	set $NAMESPACE = nmSp
 } catch err
 {
	 return "Invalid namespace: " _ nmSp _ err.Name _ " " _ err.Code
 }
 Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "NAMESPACE: " _ $NAMESPACE )
 set tProductionName = ##class(Ens.Director).GetActiveProductionName()

 if tProductionName = ""
 {
  Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Could not get active production in " _ $NAMESPACE)
  return "Could not get active production in " _ $NAMESPACE
 }
 Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Active PROD: " _ tProductionName)

 Do ##class(ITFCOMMON.SrcCtrlPkg.ItfSrcCtrlUtil).DoSvnSetup(usrNm, passwd)
 set deployComp = ""

 IF ' ##class(%File).DirectoryExists(..DeployLogDirectory)
 {
   Do ##class(%File).CreateDirectory(..DeployLogDirectory)
 }


 set fileType = $ZSTRIP($ZCVT(fileType, "U"), "<>W")

 if ( (fileType = "*") || (fileType = clsFileType) )
 {
	Set fileName = ..DeployDirectory_"Deployment_" _ clsFileType _ "_" _compNm_".xml"
 	set tSC = ..CheckoutFile(fileName, usrNm, passwd, rev )

 	if $$$ISERR(tSC)
 	{
	 	Set comment =  ##class(ITFCOMMON.Utility).getErrorMsg(tSC, "CLS CheckoutFile failed for " _ fileName)
	 	return comment
 	}
	set tSC = ..DeployClassFiles(compNm, fileName, rev, nmSp, tProductionName, usrNm, passwd, env)
 }
 if $$$ISERR(tSC)
 {
		Set comment =  ##class(ITFCOMMON.Utility).getErrorMsg(tSC, "CLS DeployClassFiles failed: " )
	 	return comment
 }
 else
 {
	 set comment = "Successfully deployed the classes. "
 }

 if ( (fileType = "*") || (fileType = cfgFileType) )
 {
	Set fileName = ..DeployDirectory_"Deployment_" _ cfgFileType _ "_" _compNm_".xml"

 	set tSC = ..CheckoutFile(fileName, usrNm, passwd, rev )

 	if $$$ISERR(tSC)
 	{
	 	Set comment = comment _ ##class(ITFCOMMON.Utility).getErrorMsg(tSC, " CONFIG CheckoutFile failed")
	 	return comment
 	}
	set tSC = ..DeployComponent(compNm, fileName, rev, nmSp, tProductionName, usrNm, passwd, env)
	if $$$ISERR(tSC)
	{
		Set comment = comment _ ##class(ITFCOMMON.Utility).getErrorMsg(tSC, " CONFIG DeployComponent failed: ")
	 	return comment
	}
	else
	{
		Set comment = comment _ " Successfully deployed the component."
	}
 }
 Set comment = comment _ " View LOG and ROLLBACK files  for " _ compNm _ " in " _ ..DeployLogDirectory
 return comment

#dim tSC As %Status = $$$OK
 if (compNm '[ "||") 
 {
  set ItemByConfigName = tProductionName_"||"_compNm
 }
 else
 {
	 set ItemByConfigName = compNm
 }

 Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(ItemByConfigName)
 If $IsObject(tItem)
 {
		Quit $$$ERROR($$$GeneralError, ItemByConfigName _ " already exists")
 }

 set parseFl = ##class(ITFCOMMON.parseXmlFile).%New()
 set tSC = parseFl.ParseFile(fileName, compNm)



 if ( ($$$ISOK(tSC)) && (parseFl.IsItfExportFile()) && (parseFl.IsConfigFile()) )
  {
	 if (parseFl.itemsInfo.GetAt(1).itemName = compNm)
	 {
 		set tSC = ..Deploy(compNm, fileName, "Config", tProductionName, usrNm)
 		if $$$ISOK(tSC)
 		{
	 		// Update Database
	 		set tSC = ..updateImpl(usrNm, passwd, compNm, fileName, rev, parseFl.itemsInfo.GetAt(1).itemInfo, env)
 		}
	 }
	 else
	 {
		 Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "File does not have config for " _ compNm)
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for " _ compNm)
	 }
  }
  else
  {
	 Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Parsing the file failed " _ tSC)
  	 Quit tSC
  }
  return tSC

	set tSC = $$$OK
	try {

		 	NEW $NAMESPACE
     		set $NAMESPACE = "ITFCOMMON"
	 		set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
	 		set depCl.Username = usrNm
		 	set depCl.Password = passwd
	 		set tSC = depCl.UpdateComponentImpl(compNm, nmSp, fileName, rev, fileInfo, env)
	 		return tSC
	} catch err
	{
		 		If $ZERROR["<ZSOAP>" {
                	Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  %objlasterror)
                	Set tSC=$$$ERROR($$$GeneralError, "Error in updating Component in DB")
		 		} Else {
            		Set tSC=$$$ERROR($$$CacheError,$ZERROR)
		 		}
	}
	return tSC

	set tSC = $$$OK
	try {

		 	NEW $NAMESPACE
     		set $NAMESPACE = "ITFCOMMON"
	 		set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
	 		set depCl.Username = usrNm
		 	set depCl.Password = passwd
	 		set tSC = depCl.UpdateClassItem(clNm , componentNm , nmSp, DeploymentFile, fileVersion, fileInfo, env)

	 		return tSC
	} catch err
	{
		 		If $ZERROR["<ZSOAP>" {
                	Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  %objlasterror)
                	Set tSC=$$$ERROR($$$GeneralError, "Error in updating class in DB")
		 		} Else {
            		Set tSC=$$$ERROR($$$CacheError,$ZERROR)
		 		}
	}
	return tSC

#dim tSC As %Status = $$$OK
 set parseFl = ##class(ITFCOMMON.parseXmlFile).%New()
 set tSC = parseFl.ParseFile(fileName, compNm)

 if ( ($$$ISOK(tSC)) && (parseFl.IsItfExportFile()) )
  {

	 if (parseFl.itemsInfo.Count() < 2)
	 {
		  Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "File does not have config for any class in file" _ compNm)
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for any class in file " _ compNm)
	 }

	 if (parseFl.itemsInfo.GetAt(1).itemName = compNm)
	 {
 		set tSC = ..Deploy(compNm, fileName, "Class", tProductionName, usrNm)
 		if $$$ISOK(tSC)
 		{
	 		// Update Database
	 		try {

	 		 set tSC = ..updateImpl(usrNm, passwd, compNm, nmSp, fileName, rev, parseFl.itemsInfo.GetAt(1).itemInfo, env)
	 		// Update Database for each class
	 		FOR ind=2:1:parseFl.itemsInfo.Count()
	 		{
		 	   set tSC = ..updateClass(usrNm, passwd, parseFl.itemsInfo.GetAt(ind).itemName, compNm, nmSp, fileName, 
	 		   parseFl.itemsInfo.GetAt(ind).versionNum, parseFl.itemsInfo.GetAt(ind).itemInfo, env)
	 		   if $$$ISERR(tSC)
	 		   {
		 		   Return tSC
	 		   }
	 		}
	 		} catch err
	 		{
		 		If $ZERROR["<ZSOAP>" {
                	Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  %objlasterror)
                	Set tSC=$$$ERROR($$$GeneralError, "Error in updating ClassItem")
		 		} Else {
            		Set tSC=$$$ERROR($$$CacheError,$ZERROR)
		 		}
	 		}
 		}
	 }
	 else
	 {
		 Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "File does not have config for " _ compNm)
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for " _ compNm)
	 }
  }
  else
  {
	 Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Parsing the file failed ")
  	 Quit $$$ERROR($$$GeneralError, "Parsing the file failed ")
  }
  Quit tSC

  #dim tSC As %Status
  #dim clsList As  %ListOfDataTypes
  set tSC = $$$OK
  NEW $NAMESPACE
  set $NAMESPACE = "ITFCOMMON"

  set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
  set depCl.Username = usrNm
  set depCl.Password = passwd
  set clsList = depCl.GetClassesForComponent(tItemName, nmSp)
  Do clsList.Insert(tItemName)

 set parseFl = ##class(ITFCOMMON.parseXmlFile).%New()
 set tSC = parseFl.ParseFile(tExportClsFilename, tItemName)

 if ( ($$$ISOK(tSC)) && (parseFl.IsItfExportFile()) )
  {

	 if (parseFl.itemsInfo.Count() < 2)
	 {
		  Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "File does not have config for any class in file" _ compNm)
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for any class in file " _ compNm)
	 }
	 if (parseFl.itemsInfo.Count() '= clsList.Count())
	 {
		 set tSC =  $$$ERROR($$$GeneralError, "Number of classes in DB and classfile do not match")
		 Quit
	 }
	 if (parseFl.itemsInfo.GetAt(1).itemName = tItemName)
	 {

	 	FOR ind=2:1:parseFl.itemsInfo.Count()
	 	{
		 	set clsNm = parseFl.itemsInfo.GetAt(ind).itemName
		 	if clsList.Find($ZCVT(clsNm, "U"))
		 	{
	   			set tSC = ..CompareClassInternalWithSrcCtrl(clsNm,nmSp,
	   	 				usrNm, passwd, env, parseFl.itemsInfo.GetAt(ind).versionNum)
	 			if $$$ISERR(tSC)
	 			{
		 			Quit
	 			}
		 	}
		 	else
		 	{
			 	set tSC =  $$$ERROR($$$GeneralError, "Could not find class name being deployed " _ clsNm)
			 	Quit
		 	}
	 	}
	 }
	 else
	 {
		 Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "File does not have config for " _ tItemName)
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for " _ tItemName)
	 }
  }
  Quit tSC

  set tSC = $$$OK
  NEW $NAMESPACE
  set $NAMESPACE = "ITFCOMMON"
  set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
  set depCl.Username = usrNm
  set depCl.Password = passwd
  set clsList = depCl.GetClassInformation(clsName, nmSp, env, revNum)
  for ind=1:1:clsList.Count()
  {
	  set retVal = clsList.GetAt(ind)
	  set clsNm = $Piece(retVal, ",", 1)
	  set clsfile = $Piece(retVal, ",", 2) 
	  set version = $Piece(retVal, ",", 3) 
	  Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   clsNm _ ", " _ clsfile _ ", " _ version)
	  set extNm = ##class(ITFCOMMON.SrcCtrlPkg.ItfSrcCtrlUtil).ExternalName(clsNm)
	  Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   extNm)

	  set cmd = "svn update  -N --no-auth-cache --non-interactive --revision " _ version _ " --username " _ usrNm _ " --password " _ passwd _ " " _extNm
	  set stat = $ZF(-1, cmd)
	  Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "cmd: " _cmd _ ": " _ stat)
	  if (stat = 0)
	  {
		     // Export internal code
		     set tempFile = ##class(%Library.File).TempFilename()
		     if $F(clsNm, "CLS") >  $L(clsNm)
			 {
				set item = clsNm
	 		 }
	 		 else
	 		 {
				set item = clsNm _ "." _ "CLS"
	 		 }
			 Do ..exportFile(tempFile, item, nmSp)
			 if (  ##class(%File).Exists(tempFile))
			 {
			     	set tempFile2 = ##class(%Library.File).TempFilename()
			     	set cmd = "diff -w -B --suppress-common-lines " _ extNm _ " " _ tempFile _ " > " _ tempFile2
			   		Set stat = $ZF(-1, cmd)
			      	Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   cmd _ " Stat: " _ stat)
			   	    if (##class(%File).Exists(tempFile2))
			   	    {
				   	    if ##class(%File).GetFileSize(tempFile2) > 0
			   			{
				   			set tSC = $$$ERROR($$$GeneralError, "Src Control File is not current for " _ item)
				   			Quit
			   			}
         				Do ##class(%Library.File).Delete(tempFile2)
         				Do ##class(%Library.File).Delete(tempFile)
			   	    }
			   	    else
			   	    {
				   	    set tSC = $$$ERROR($$$GeneralError, "diff failed for " _ item)
				   	    Quit 
			   	    }
			 }
			 else
			 {
			     	set tSC = $$$ERROR($$$GeneralError, " Export failed: " _ item )
			     	Quit
			 }
		}
		else
		{
		   set tSC = $$$ERROR($$$GeneralError, "Unable to run svn update command for: " _ extNm)
		   Quit
		}
    }

	if $$$ISOK(tSC)
	{
		Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   " SVN file content matches internal code " _ clsName)
	}


  QUIT tSC

	set tSC = $$$OK
	if (rev '= "")
	{
		Do ##class(%File).Delete(fileNm)
		Set cmd= $$$SVNUPDATE _ " --revision " _ rev
		Set cmd= cmd _ " --username " _ usrNm _ " --password " _ passwd _ " " _  fileNm 

		Set status = $ZF(-1, cmd)

		if (status '= 0)
		{
			set tSC = $$$ERROR($$$GeneralError, $$$SVNUPDATE _ " --revision " _ rev _ " failed")
		}
		if ##class(%File).Exists(fileNm)
		{
			Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Checked out " _ fileNm _ ", version: " _ rev)
		}
		else {
  			Do ##class(ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Could not find file " _ fileNm)
  			set tSC = $$$ERROR($$$GeneralError, "Could not find file " _ fileNm)
 		}
	}
	else
	{		
		  set tSC = $$$ERROR($$$GeneralError, "Checkout: Revision number is required") 
	}

 	Quit tSC
